$root=dirname(__DIR__);define('TR_PRIVATE',$root.'/.runtime/qa/private');define('TR_RELEASE',TR_PRIVATE.'/releases/1.0.0');define('APP_VERSION','1.0.0');foreach(['core','domain','api','salaries','annual','updates','profile','contracts','people'] as $f)require TR_RELEASE.'/app/'.$f.'.php';$_SESSION=[];$_GET=['tenant'=>'DEMONSTRACAO'];$checks=[];
