no(fn()=>personContacts(array_replace($data,['email'=>'inválido'])),400,'E-mail inválido recusado');no(fn()=>personContacts(array_replace($data,['postalCode'=>'123'])),400,'CEP inválido recusado');no(fn()=>personContacts(array_replace($data,['state'=>'XX'])),400,'UF inválida recusada');no(fn()=>personContacts(['street'=>'Endereço incompleto']),400,'Endereço parcial recusado');
$viewer=one('SELECT * FROM tr_users WHERE email=?',['consulta@demonstracao.invalid']);no(fn()=>routeApi($viewer,'person-contact','POST',['linkId'=>$same[0]['id'],'version'=>$same[0]['version'],'data'=>$data]),403,'Consulta não altera dados pessoais');$commission=one('SELECT * FROM tr_users WHERE email=?',['comissao.geral.1@demonstracao.invalid']);$cw=routeApi($commission,'workspace','GET',[]);ok(!array_filter($cw['links'],fn($p)=>$p['personId']!==$commission['person']&&(isset($p['residentialAddress'])||isset($p['alternatePhone']))),'Comissão não recebe endereço nem telefones de terceiros');
